//! Curves and signature algorithms used by the Kazakhstan PKI (NCA RK).
//!
//! Both curves have prime order (cofactor 1), as the [`crate::hazmat`] formulas require; every
//! on-curve point other than the identity therefore lies in the subgroup generated by `G`.

use crate::hash::{gost34311, streebog512};
use crate::hazmat::CurveParams;
use std::sync::LazyLock;

/// GOST 34.310-2004 PKIGOVKZ-A: the same curve as RFC 4357 CryptoPro-A.
static PKIGOVKZ_2004_A: LazyLock<CurveParams> = LazyLock::new(|| {
    CurveParams::from_hex(
        "FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFD97",
        "FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFD94",
        "A6",
        "FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF6C611070995AD10045841B09B761B893",
        "1",
        "8D91E471E0989CDA27DF505A453F2B7635294F2DDF23E3B122ACC99C9E9F1E14",
    )
});

/// GOST 34.10-2015 512-bit ParamSetA: the same curve as RFC 7836 id-tc26-gost-3410-12-512-paramSetA.
static TC26_512_A: LazyLock<CurveParams> = LazyLock::new(|| {
    CurveParams::from_hex(
        "FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF\
         FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFDC7",
        "FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF\
         FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFDC4",
        "E8C2505DEDFC86DDC1BD0B2B6667F1DA34B82574761CB0E879BD081CFD0B6265\
         EE3CB090F30D27614CB4574010DA90DD862EF9D4EBEE4761503190785A71C760",
        "FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF\
         27E69532F48D89116FF22B8D4E0560609B4B38ABFAD2B85DCACDB1411F10B275",
        "3",
        "7503CFE87A836AE3A61B8816E25450E6CE5E1C93ACF1ABC1778064FDCBEFA921\
         DF1626BE4FD036E93D75E6A50E3A41E98028FE5FC235F5B889A589CB5215F2A4",
    )
});

/// Elliptic-curve parameter set of a KZ GOST key.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum CurveId {
    /// GOST 34.310-2004 PKIGOVKZ-A (= CryptoPro-A, RFC 4357), 256-bit.
    Pkigovkz2004A,
    /// GOST 34.10-2015 512-bit ParamSetA (= TC26 512 paramSetA, RFC 7836).
    Tc26_512A,
}

impl CurveId {
    /// Curve constants.
    pub fn params(self) -> &'static CurveParams {
        match self {
            CurveId::Pkigovkz2004A => &PKIGOVKZ_2004_A,
            CurveId::Tc26_512A => &TC26_512_A,
        }
    }

    /// Byte length of a coordinate, and of each half of a signature: 32 or 64.
    pub fn coord_len(self) -> usize {
        match self {
            CurveId::Pkigovkz2004A => 32,
            CurveId::Tc26_512A => 64,
        }
    }

    /// `publicKeyParamSet` OID in the SPKI algorithm parameters.
    pub fn curve_oid(self) -> &'static str {
        match self {
            CurveId::Pkigovkz2004A => "1.2.398.3.10.1.1.1.1.1",
            CurveId::Tc26_512A => "1.2.398.3.10.1.1.2.2.1",
        }
    }

    /// `digestParamSet` OID in the SPKI algorithm parameters.
    pub fn digest_param_oid(self) -> &'static str {
        match self {
            CurveId::Pkigovkz2004A => "1.2.398.3.10.1.3.1.1.0",
            CurveId::Tc26_512A => "1.2.398.3.10.1.3.3",
        }
    }

    /// Public-key algorithm OID (SPKI / PKCS#8 `AlgorithmIdentifier`).
    pub fn key_oid(self) -> &'static str {
        match self {
            CurveId::Pkigovkz2004A => "1.2.398.3.10.1.1.1.1",
            CurveId::Tc26_512A => "1.2.398.3.10.1.1.2.2",
        }
    }

    /// Inverse of [`CurveId::curve_oid`].
    pub fn from_curve_oid(oid: &str) -> Option<CurveId> {
        [CurveId::Pkigovkz2004A, CurveId::Tc26_512A]
            .into_iter()
            .find(|c| c.curve_oid() == oid)
    }
}

/// KZ GOST signature algorithm: hash plus curve.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum GostAlg {
    /// GOST 34.311-95 hash with GOST 34.310-2004 on PKIGOVKZ-A.
    Gost34310_2004,
    /// GOST 34.11-2015 (Streebog-512) hash with GOST 34.10-2015 on the 512-bit ParamSetA.
    Gost3410_2015_512,
}

impl GostAlg {
    /// Curve of the keys this algorithm signs with.
    pub fn curve(self) -> CurveId {
        match self {
            GostAlg::Gost34310_2004 => CurveId::Pkigovkz2004A,
            GostAlg::Gost3410_2015_512 => CurveId::Tc26_512A,
        }
    }

    /// Signature algorithm OID (certificates, CMS `SignerInfo.signatureAlgorithm`).
    pub fn signature_oid(self) -> &'static str {
        match self {
            GostAlg::Gost34310_2004 => "1.2.398.3.10.1.1.1.2",
            GostAlg::Gost3410_2015_512 => "1.2.398.3.10.1.1.2.3.2",
        }
    }

    /// Digest algorithm OID (CMS `digestAlgorithm`).
    pub fn digest_oid(self) -> &'static str {
        match self {
            GostAlg::Gost34310_2004 => "1.2.398.3.10.1.3.1",
            GostAlg::Gost3410_2015_512 => "1.2.398.3.10.1.3.3",
        }
    }

    /// Digest of `data` with this algorithm's hash: 32 or 64 bytes.
    pub fn hash(self, data: &[u8]) -> Vec<u8> {
        match self {
            GostAlg::Gost34310_2004 => gost34311(data).to_vec(),
            GostAlg::Gost3410_2015_512 => streebog512(data).to_vec(),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::hazmat::is_on_curve;

    #[test]
    fn base_points_lie_on_their_curves() {
        for curve in [CurveId::Pkigovkz2004A, CurveId::Tc26_512A] {
            let c = curve.params();
            assert!(is_on_curve(c, &c.gx, &c.gy));
            assert_eq!(c.p.bits_precision() as usize, 8 * curve.coord_len());
        }
    }
}
